<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Milestones, Tasks & Production Calendar V8 */
function tuff_beatz_project_milestones($id){$v=get_post_meta((int)$id,'_tb_milestones_v8',true);return is_array($v)?array_values($v):array();}
function tuff_beatz_project_activity($id){$v=get_post_meta((int)$id,'_tb_activity_v8',true);return is_array($v)?array_values($v):array();}
function tuff_beatz_add_activity($id,$type,$message,$user_id=0){$a=tuff_beatz_project_activity($id);$u=$user_id?get_userdata($user_id):wp_get_current_user();$a[]=array('id'=>wp_generate_uuid4(),'type'=>sanitize_key($type),'message'=>sanitize_text_field($message),'user_id'=>(int)($u->ID??0),'name'=>sanitize_text_field($u->display_name??'TUFF BEATZ'),'time'=>current_time('mysql'));if(count($a)>200)$a=array_slice($a,-200);update_post_meta($id,'_tb_activity_v8',$a);}
function tuff_beatz_default_milestones(){return array(
 array('title'=>'Deposit Paid','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Project is financially cleared to begin.'),
 array('title'=>'Stems / Source Files Due','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Client delivers all required source files.'),
 array('title'=>'Production','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Core production, arrangement and recording work.'),
 array('title'=>'Mix V1','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'First review mix delivered to client.'),
 array('title'=>'Client Review','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Client reviews and submits timestamped notes.'),
 array('title'=>'Mix Approval','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Approved mix is locked for mastering.'),
 array('title'=>'Mastering','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Final mastering and quality control.'),
 array('title'=>'Final Delivery','status'=>'pending','due_date'=>'','assignee'=>0,'notes'=>'Final approved deliverables released to client.')
 );}
function tuff_beatz_ensure_milestones($id){$m=tuff_beatz_project_milestones($id);if($m)return $m;$m=array();foreach(tuff_beatz_default_milestones() as $x){$x['id']=wp_generate_uuid4();$x['created_at']=current_time('mysql');$m[]=$x;}update_post_meta($id,'_tb_milestones_v8',$m);tuff_beatz_add_activity($id,'timeline','Production timeline created');return $m;}
function tuff_beatz_milestone_statuses(){return array('pending'=>'Pending','in-progress'=>'In Progress','waiting'=>'Waiting','completed'=>'Completed','blocked'=>'Blocked');}
function tuff_beatz_milestone_assignees($id){$out=array();$p=get_post($id);if($p&&$p->post_author){$u=get_userdata($p->post_author);if($u)$out[$u->ID]=$u->display_name.' — Project Owner';}foreach(tuff_beatz_project_collaborators($id) as $c){$uid=(int)($c['user_id']??0);if($uid)$out[$uid]=($c['name']??$c['email']??'Collaborator').' — '.($c['role']??'collaborator');}return $out;}
function tuff_beatz_milestone_admin_box($post){$m=tuff_beatz_ensure_milestones($post->ID);$users=tuff_beatz_milestone_assignees($post->ID);$statuses=tuff_beatz_milestone_statuses();echo '<p>Manage production milestones, assignments and due dates. Changes appear in the client workspace.</p><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">Milestone</th><th>Status</th><th>Due</th><th>Assignee</th></tr></thead><tbody>';foreach($m as $x){echo '<tr><td style="padding:7px 4px"><strong>'.esc_html($x['title']).'</strong><br><small>'.esc_html($x['notes']??'').'</small></td><td><select name="tb_ms_status['.esc_attr($x['id']).']">';foreach($statuses as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($x['status']??'pending',$v,false).'>'.esc_html($l).'</option>';echo '</select></td><td><input type="date" name="tb_ms_due['.esc_attr($x['id']).']" value="'.esc_attr($x['due_date']??'').'"></td><td><select name="tb_ms_assignee['.esc_attr($x['id']).']"><option value="0">Unassigned</option>';foreach($users as $uid=>$name)echo '<option value="'.esc_attr($uid).'" '.selected((int)($x['assignee']??0),(int)$uid,false).'>'.esc_html($name).'</option>';echo '</select></td></tr>';}echo '</tbody></table><hr><p><strong>Add Custom Task / Milestone</strong></p><p><input style="width:49%" name="tb_new_ms_title" placeholder="Task or milestone title"> <input type="date" name="tb_new_ms_due"></p><p><textarea style="width:100%;min-height:70px" name="tb_new_ms_notes" placeholder="Notes / deliverable / requirement"></textarea></p>';wp_nonce_field('tb_milestones_save_'.$post->ID,'tb_milestones_nonce');}
function tuff_beatz_milestone_metabox(){add_meta_box('tb_milestones_v8',__('Milestones, Tasks & Production Calendar V8','tuff-beatz'),'tuff_beatz_milestone_admin_box','tb_request','normal','high');}add_action('add_meta_boxes_tb_request','tuff_beatz_milestone_metabox');
function tuff_beatz_save_milestones($id){if(!isset($_POST['tb_milestones_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_milestones_nonce'])),'tb_milestones_save_'.$id)||!current_user_can('edit_post',$id))return;$m=tuff_beatz_ensure_milestones($id);$statuses=tuff_beatz_milestone_statuses();$s=(array)($_POST['tb_ms_status']??array());$d=(array)($_POST['tb_ms_due']??array());$a=(array)($_POST['tb_ms_assignee']??array());foreach($m as &$x){$mid=$x['id'];$old=$x['status']??'pending';$new=sanitize_key($s[$mid]??$old);if(!isset($statuses[$new]))$new=$old;$x['status']=$new;$x['due_date']=sanitize_text_field($d[$mid]??'');$x['assignee']=(int)($a[$mid]??0);if($new!==$old)tuff_beatz_add_activity($id,'milestone',$x['title'].' → '.$statuses[$new]);}unset($x);$title=sanitize_text_field(wp_unslash($_POST['tb_new_ms_title']??''));if($title){$m[]=array('id'=>wp_generate_uuid4(),'title'=>$title,'status'=>'pending','due_date'=>sanitize_text_field(wp_unslash($_POST['tb_new_ms_due']??'')),'assignee'=>0,'notes'=>sanitize_textarea_field(wp_unslash($_POST['tb_new_ms_notes']??'')),'created_at'=>current_time('mysql'));tuff_beatz_add_activity($id,'task','Added: '.$title);}update_post_meta($id,'_tb_milestones_v8',$m);}
add_action('save_post_tb_request','tuff_beatz_save_milestones',40);
function tuff_beatz_toggle_milestone(){ $id=(int)($_POST['request_id']??0);$mid=sanitize_text_field(wp_unslash($_POST['milestone_id']??''));$r=tuff_beatz_project_dashboard_url($id).'#timeline';if(!is_user_logged_in()||!tuff_beatz_project_owner_or_admin($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_ms_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_ms_nonce'])),'tb_toggle_ms_'.$id.'_'.$mid)){wp_safe_redirect($r);exit;}$m=tuff_beatz_ensure_milestones($id);foreach($m as &$x)if(($x['id']??'')===$mid){$x['status']=($x['status']??'')==='completed'?'in-progress':'completed';tuff_beatz_add_activity($id,'milestone',$x['title'].' → '.(($x['status']==='completed')?'Completed':'In Progress'));break;}unset($x);update_post_meta($id,'_tb_milestones_v8',$m);wp_safe_redirect($r);exit;}
add_action('admin_post_tb_toggle_milestone','tuff_beatz_toggle_milestone');
function tuff_beatz_render_milestones_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!tuff_beatz_user_project_permission($id,'view'))return;$m=tuff_beatz_ensure_milestones($id);$activity=array_reverse(tuff_beatz_project_activity($id));$users=tuff_beatz_milestone_assignees($id);$manage=tuff_beatz_project_owner_or_admin($id);$done=count(array_filter($m,function($x){return ($x['status']??'')==='completed';}));$pct=count($m)?round($done/count($m)*100):0;usort($m,function($a,$b){$ad=$a['due_date']??'';$bd=$b['due_date']??'';if(!$ad)return 1;if(!$bd)return -1;return strcmp($ad,$bd);});echo '<template id="tb-timeline-template"><section id="timeline" class="tb-portal-card tb-workspace-section tb-timeline"><p class="tb-card-kicker">PRODUCTION CONTROL V8</p><h2>Milestones, Tasks & Calendar</h2><div class="tb-timeline-progress"><div><strong>'.esc_html($pct).'%</strong><span>PROJECT PROGRESS</span></div><div class="tb-progress-rail"><i style="width:'.esc_attr($pct).'%"></i></div></div><div class="tb-milestone-list">';foreach($m as $x){$uid=(int)($x['assignee']??0);$due=$x['due_date']??'';$over=$due&&$x['status']!=='completed'&&strtotime($due.' 23:59:59')<current_time('timestamp');echo '<article class="tb-ms tb-ms--'.esc_attr($x['status']??'pending').($over?' tb-ms--overdue':'').'"><div class="tb-ms-dot">'.(($x['status']??'')==='completed'?'✓':'').'</div><div><small>'.esc_html(strtoupper(str_replace('-',' ',$x['status']??'pending'))).'</small><h3>'.esc_html($x['title']).'</h3><p>'.esc_html($x['notes']??'').'</p><span>'.($due?'Due '.esc_html(mysql2date('M j, Y',$due)):'No due date').($uid&&isset($users[$uid])?' • '.esc_html($users[$uid]):'').'</span></div>';if($manage){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_toggle_milestone"><input type="hidden" name="request_id" value="'.esc_attr($id).'"><input type="hidden" name="milestone_id" value="'.esc_attr($x['id']).'">';wp_nonce_field('tb_toggle_ms_'.$id.'_'.$x['id'],'tb_ms_nonce');echo '<button type="submit">'.(($x['status']??'')==='completed'?'Reopen':'Complete').'</button></form>';}echo '</article>';}echo '</div><div class="tb-activity"><h3>Project Activity</h3>';if($activity){foreach(array_slice($activity,0,30) as $a)echo '<div><i></i><p><strong>'.esc_html($a['message']??'Update').'</strong><span>'.esc_html(($a['name']??'TUFF BEATZ').' • '.mysql2date('M j, Y g:i a',$a['time']??'')).'</span></p></div>';}else echo '<p class="tb-empty-state">No timeline activity yet.</p>';echo '</div></section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-timeline-template"),overview=document.getElementById("overview"),nav=document.querySelector(".tb-dashboard-nav");if(t&&overview)overview.parentNode.insertBefore(t.content.cloneNode(true),overview.nextSibling);if(nav){var a=document.createElement("a");a.href="#timeline";a.textContent="Timeline";var f=nav.querySelector("a[href=\"#files\"]");if(f)nav.insertBefore(a,f);else nav.appendChild(a);}});</script>';}
add_action('wp_footer','tuff_beatz_render_milestones_workspace',7);
